    pattern = re.compile(r'\*\*(oauth-s01-t02-\d{6})\*\* \| System: (\S+) \| Status: (\S+)')
    with open(path, encoding='utf-8') as f:
        for line in f:
            m = pattern.search(line)
            if m:
                recs[m.group(1)] = (m.group(2), m.group(3))
    return recs

def parse_jsonl(path):
    recs = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line=line.strip()
            if not line: continue
            rec = json.loads(line)
            recs[rec['case']] = (rec['system'], rec['status'])
    return recs

def parse_csv(path):
    recs = {}
    with open(path, encoding='utf-8', newline='') as f:
        for row in csv.DictReader(f):
            recs[row['case']] = (row['system'], row['status'])
    return recs

def parse_yaml(path):
    with open(path, encoding='utf-8') as f:
        data = yaml.safe_load(f.read().split(chr(10),1)[1])
    recs = {}
    for item in data:
        recs[item['case']] = (item['system'], item['status'])
    return recs

