import json, csv, re

def parse_md_or_yaml(path, is_yaml):
    text = open(path, encoding='utf-8').read()
    if is_yaml:
        pattern = re.compile(r'- case: (\S+)\s*\n\s*system: (\S+)\s*\n\s*status: (\S+)\s*\n\s*note: \"(.*?)\"', re.M)
    else:
        pattern = re.compile(r'\*\*(\S+)\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.*)')
    records = {}
    for m in pattern.finditer(text):
        case, system, status, note = m.groups()
        records[case] = (system, status, note.strip())
    return records

md = parse_md_or_yaml('oauth-s01-t05-evidence-01.md', is_yaml=False)
yaml_ = parse_md_or_yaml('oauth-s01-t05-evidence-04.yaml', is_yaml=True)

jsonl = {}
for line in open('oauth-s01-t05-evidence-02.jsonl', encoding='utf-8'):
    line = line.strip()
    if not line: continue
    r = json.loads(line)
    jsonl[r['case']] = (r['system'], r['status'], r['note'])

csvd = {}
with open('oauth-s01-t05-evidence-03.csv', encoding='utf-8', newline='') as f:
    for r in csv.DictReader(f):
        csvd[r['case']] = (r['system'], r['status'], r['note'])

files = {'md': md, 'jsonl': jsonl, 'csv': csvd, 'yaml': yaml_}
for name, d in files.items():
    keys = sorted(d.keys())
    print(name, 'count=', len(d), 'min=', keys[0], 'max=', keys[-1])

for name, d in files.items():
    nums = sorted(int(k.split('-')[-1]) for k in d.keys())
    contiguous = nums == list(range(nums[0], nums[-1]+1))
    print(name, 'contiguous:', contiguous)

names = list(files.keys())
mismatches = []
for i in range(len(names)):
    for j in range(i+1, len(names)):
        a, b = files[names[i]], files[names[j]]
        shared = set(a) & set(b)
        for k in shared:
            if a[k] != b[k]:
                mismatches.append((names[i], names[j], k, a[k], b[k]))
