cd "maintenance/inputs/oauth-s01/scope-catalog-changes" && python - <<'EOF'
import json, re, csv

def parse_md(path):
    out = {}
    with open(path, encoding="utf-8") as f:
        for line in f:
            m = re.match(r"- \*\*(oauth-s01-t07-\d+)\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.*)", line.strip())
            if m:
                case, system, status, note = m.groups()
                out[case] = {"system": system, "status": status, "note": note}
    return out

def parse_jsonl(path):
    out = {}
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            rec = json.loads(line)
            out[rec["case"]] = {"system": rec["system"], "status": rec["status"], "note": rec["note"]}
    return out

def parse_csv(path):
    out = {}
    with open(path, encoding="utf-8", newline="") as f:
        for row in csv.DictReader(f):
            out[row["case"]] = {"system": row["system"], "status": row["status"], "note": row["note"]}
    return out

def parse_yaml(path):
    out = {}
    case = None
    cur = {}
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.rstrip("\n")
            m = re.match(r"- case: (oauth-s01-t07-\d+)", line)
            if m:
                if case:
                    out[case] = cur
                case = m.group(1)
                cur = {}
                continue
            m = re.match(r"\s+system: (\S+)", line)
            if m:
                cur["system"] = m.group(1)
                continue
            m = re.match(r"\s+status: (\S+)", line)
            if m:
                cur["status"] = m.group(1)
                continue
            m = re.match(r'\s+note: "(.*)"', line)
            if m:
                cur["note"] = m.group(1)
        if case:
            out[case] = cur
    return out

md = parse_md("oauth-s01-t07-evidence-01.md")
jl = parse_jsonl("oauth-s01-t07-evidence-02.jsonl")
cs = parse_csv("oauth-s01-t07-evidence-03.csv")
ya = parse_yaml("oauth-s01-t07-evidence-04.yaml")

print("counts:", len(md), len(jl), len(cs), len(ya))

sources = {"md": md, "jsonl": jl, "csv": cs, "yaml": ya}
all_cases = set()
for d in sources.values():
    all_cases |= set(d.keys())

mismatches = 0
for case in sorted(all_cases):
    present = {name: d[case] for name, d in sources.items() if case in d}
    if len(present) < 2:
        continue
    values = list(present.values())
    first = values[0]
    for v in values[1:]:
        if v != first:
            mismatches += 1
            print("MISMATCH", case, present)

print("total mismatches across shared cases:", mismatches)

# cycle check
cyc_system = [md[f"oauth-s01-t07-{i:06d}"]["system"] for i in range(1, 9)]
cyc_status = [md[f"oauth-s01-t07-{i:06d}"]["status"] for i in range(1, 9)]
print("system cycle (first 8):", cyc_system)
print("status cycle (first 8):", cyc_status)

# csv-only extra cases
extra = sorted(set(cs.keys()) - set(md.keys()), key=lambda c: int(c.split("-")[-1]))
print("csv-only extra cases:", extra)
missing_from_jsonl = sorted(set(md.keys()) - set(jl.keys()), key=lambda c: int(c.split("-")[-1]))
print("cases in md but not jsonl:", missing_from_jsonl)
EOF

