input.command:
cd "maintenance/inputs/oauth-s01/expiry-window-observations/" && python3 -c "
import json, csv, re

# Parse md
md_cases = {}
with open('oauth-s01-t10-evidence-01.md', encoding='utf-8') as f:
    for line in f:
        m = re.match(r'- \*\*(oauth-s01-t10-\d+)\*\* \| System: ([\w-]+) \| Status: ([\w-]+) \| Evidence: (.*)', line.strip())
        if m:
            md_cases[m.group(1)] = (m.group(2), m.group(3), m.group(4))

# Parse jsonl
jsonl_cases = {}
with open('oauth-s01-t10-evidence-02.jsonl', encoding='utf-8') as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        d = json.loads(line)
        jsonl_cases[d['case']] = (d['system'], d['status'], d['note'])

# Parse csv
csv_cases = {}
with open('oauth-s01-t10-evidence-03.csv', encoding='utf-8', newline='') as f:
    reader = csv.DictReader(f)
    for row in reader:
        csv_cases[row['case']] = (row['system'], row['status'], row['note'])

# Parse yaml (simple line-based parse since format is regular)
yaml_cases = {}
with open('oauth-s01-t10-evidence-04.yaml', encoding='utf-8') as f:
    lines = [l.rstrip('\n').rstrip('\r') for l in f]
cur = {}
cur_case = None
for line in lines:
