cd "maintenance/inputs/oauth-s01/loopback-browser-matrix/" && python -c "
import json, csv, re

md_cases = {}
with open('oauth-s01-t11-evidence-01.md', encoding='utf-8') as f:
    for line in f:
        m = re.match(r'- \*\*(oauth-s01-t11-\d+)\*\* \| System: ([\w-]+) \| Status: ([\w-]+) \| Evidence: (.*)', line.strip())
        if m:
            md_cases[m.group(1)] = (m.group(2), m.group(3), m.group(4))

jsonl_cases = {}
with open('oauth-s01-t11-evidence-02.jsonl', encoding='utf-8') as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        d = json.loads(line)
        jsonl_cases[d['case']] = (d['system'], d['status'], d['note'])

csv_cases = {}
with open('oauth-s01-t11-evidence-03.csv', encoding='utf-8', newline='') as f:
    reader = csv.DictReader(f)
    for row in reader:
        csv_cases[row['case']] = (row['system'], row['status'], row['note'])

yaml_cases = {}
with open('oauth-s01-t11-evidence-04.yaml', encoding='utf-8') as f:
    lines = [l.rstrip('\n').rstrip('\r') for l in f]
cur = {}
cur_case = None
for line in lines:
    line = line.strip()
    if line.startswith('- case:'):
        if cur_case:
            yaml_cases[cur_case] = (cur['system'], cur['status'], cur['note'])
        cur_case = line.split(':',1)[1].strip()
        cur = {}
    elif line.startswith('system:'):
        cur['system'] = line.split(':',1)[1].strip()
    elif line.startswith('status:'):
        cur['status'] = line.split(':',1)[1].strip()
    elif line.startswith('note:'):
        cur['note'] = line.split(':',1)[1].strip().strip('\"')
if cur_case:
    yaml_cases[cur_case] = (cur['system'], cur['status'], cur['note'])

print('md count:', len(md_cases), 'min/max:', min(md_cases), max(md_cases))
print('jsonl count:', len(jsonl_cases), 'min/max:', min(jsonl_cases), max(jsonl_cases))
print('csv count:', len(csv_cases), 'min/max:', min(csv_cases), max(csv_cases))
print('yaml count:', len(yaml_cases), 'min/max:', min(yaml_cases), max(yaml_cases))

print()
print('md == yaml (same keys+values)?', md_cases == yaml_cases)

jsonl_keys = set(jsonl_cases)
md_keys = set(md_cases)
csv_keys = set(csv_cases)
print('jsonl subset of md keys?', jsonl_keys <= md_keys)
print('md subset of csv keys?', md_keys <= csv_keys)
print('jsonl missing from md (in md not jsonl):', sorted(md_keys - jsonl_keys))
print('csv extra beyond md (in csv not md):', sorted(csv_keys - md_keys))

mismatches = []
for k in md_keys & jsonl_keys:
    if md_cases[k] != jsonl_cases[k]:
        mismatches.append(('md-jsonl', k))
for k in md_keys & csv_keys:
    if md_cases[k] != csv_cases[k]:
        mismatches.append(('md-csv', k))
print('field mismatches:', mismatches)

def casenum(k):
    return int(k.split('-')[-1])

cycle = {}
for k,(sys_,status,note) in md_cases.items():
    n = casenum(k)
    cycle.setdefault(n % 4, set()).add((sys_, status))
for m in sorted(cycle):
    print('mod4=%d ->' % m, cycle[m])
"

