import json, csv, re

def parse_md_or_yaml(path, is_yaml):
    records = {}
    text = open(path, encoding='utf-8').read()
    if is_yaml:
        pattern = re.compile(r'- case: (\S+)\s+system: (\S+)\s+status: (\S+)\s+note: \"(.*?)\"', re.S)
    else:
        pattern = re.compile(r'\*\*(\S+)\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.*?)$', re.M)
    for m in pattern.finditer(text):
        case, system, status, note = m.groups()
        records[case] = (system, status, note.strip())
    return records

def parse_jsonl(path):
    records = {}
    for line in open(path, encoding='utf-8'):
        line = line.strip()
        if not line:
            continue
        d = json.loads(line)
        records[d['case']] = (d['system'], d['status'], d['note'])
    return records

def parse_csv(path):
    records = {}
    with open(path, encoding='utf-8', newline='') as f:
        for row in csv.DictReader(f):
            records[row['case']] = (row['system'], row['status'], row['note'])
    return records

md = parse_md_or_yaml('oauth-s01-t13-evidence-01.md', False)
jsonl = parse_jsonl('oauth-s01-t13-evidence-02.jsonl')
csvd = parse_csv('oauth-s01-t13-evidence-03.csv')
yaml_ = parse_md_or_yaml('oauth-s01-t13-evidence-04.yaml', True)

files = {'md': md, 'jsonl': jsonl, 'csv': csvd, 'yaml': yaml_}
for name, recs in files.items():
    keys = sorted(recs.keys())
    print(name, 'count=', len(recs), 'first=', keys[0] if keys else None, 'last=', keys[-1] if keys else None)

# pairwise diff
names = list(files.keys())
mismatches = 0
for i in range(len(names)):
    for j in range(i+1, len(names)):
        a, b = files[names[i]], files[names[j]]
        common = set(a) & set(b)
        for k in common:
            if a[k] != b[k]:
                mismatches += 1
                print('MISMATCH', names[i], names[j], k, a[k], b[k])
print('total mismatches:', mismatches)

systems = set()
statuses = set()
for recs in files.values():
    for v in recs.values():
        systems.add(v[0])
        statuses.add(v[1])
print('systems:', sorted(systems))
print('statuses:', sorted(statuses))

# check cycle in md
md_keys_sorted = sorted(md.keys(), key=lambda k: int(k.split('-')[-1]))
cycle = [md[k][:2] for k in md_keys_sorted[:4]]
print('first 4 cycle (system,status):', cycle)
ok = True
for idx, k in enumerate(md_keys_sorted):
    expected = cycle[idx % 4]
    if md[k][:2] != expected:
        ok = False
        print('cycle break at', k, md[k][:2])
print('cycle holds for all md records:', ok)
"

