    server: "OAuthHTTPServer"

    def log_message(self, format: str, *args) -> None:  # noqa: A002 - stdlib signature
        pass

    def do_POST(self) -> None:  # noqa: N802 - stdlib naming convention
        route = _ROUTES.get(self.path)
